changeSet.sql:
SET QUOTED_IDENTIFIER ON;
IF COL_LENGTH(N'app.TenantStorageConnections', N'StoreProgressPhotos') IS NULL
    ALTER TABLE app.TenantStorageConnections ADD StoreProgressPhotos BIT NOT NULL CONSTRAINT DF_TenantStorageConnections_StoreProgressPhotos DEFAULT (1);
IF COL_LENGTH(N'app.TenantStorageConnections', N'ProgressFolderId') IS NULL
    ALTER TABLE app.TenantStorageConnections ADD ProgressFolderId NVARCHAR(128) NULL;
IF COL_LENGTH(N'app.TenantStorageConnections', N'ProgressFolderName') IS NULL
    ALTER TABLE app.TenantStorageConnections ADD ProgressFolderName NVARCHAR(200) NULL;
